import { TypedSupabaseClient } from '@/utils/supabase/client';

/** Bulk clock-out for today. Timestamps are generated by the database. */
export async function clockOutChildren(client: TypedSupabaseClient, childIds: string[]): Promise<void> {
  const { error } = await client.rpc('clock_out_children', { child_ids: childIds });

  if (error) {
    throw new Error(`Failed to clock out children: ${error.message}`);
  }
}
